<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ArrowRightLeft, Plus, RotateCcw } from 'lucide-vue-next'
import SectionPanel from '../components/SectionPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { accountingApi, type AccountRecord, type ExpenseRecord, type FinancialAccountRecord, type TransferRecord } from '../api/accounting'
import type { CurrencyUnit } from '../utils/currency'
import { formatMoney, parseMoneyInput } from '../utils/currency'
import { currentCanonicalDate, formatDateTime } from '../utils/date'

const props=defineProps<{tab:string;currencyUnit:CurrencyUnit;accounts:AccountRecord[];financial:FinancialAccountRecord[];suppliers:any[]}>();const emit=defineEmits<{notify:[string]}>();const expenses=ref<ExpenseRecord[]>([]);const transfers=ref<TransferRecord[]>([]);const error=ref('');const expense=ref({categoryAccountId:'ACC-EXP-OTHER',financialAccountId:'FIN-CASH',description:'',payee:'',supplierId:'',amount:'',paymentMethod:'cash'});const transfer=ref({sourceFinancialAccountId:'FIN-CASH',destinationFinancialAccountId:'FIN-BANK',amount:'',reference:'',transferDate:currentCanonicalDate()})
async function load(){try{[expenses.value,transfers.value]=await Promise.all([accountingApi.expenses(),accountingApi.transfers()])}catch(e){error.value=String(e)}}onMounted(load)
async function createExpense(){try{const amount=parseMoneyInput(expense.value.amount,props.currencyUnit);if(!amount||amount<=0)throw new Error('Enter a positive amount');const v=await accountingApi.createExpense({...expense.value,amountRial:amount});expenses.value=[v,...expenses.value];expense.value={...expense.value,description:'',payee:'',amount:''};emit('notify','Expense posted.')}catch(e){error.value=String(e)}}
async function createTransfer(){try{const amount=parseMoneyInput(transfer.value.amount,props.currencyUnit);if(!amount||amount<=0)throw new Error('Enter a positive amount');const v=await accountingApi.createTransfer({...transfer.value,amountRial:amount});transfers.value=[v,...transfers.value];transfer.value={...transfer.value,amount:'',reference:''};emit('notify','Transfer posted.')}catch(e){error.value=String(e)}}
async function reverseExpense(v:ExpenseRecord){try{const next=await accountingApi.reverseExpense(v.id);expenses.value=expenses.value.map(x=>x.id===next.id?next:x);emit('notify','Expense reversed.')}catch(e){error.value=String(e)}}
async function reverseTransfer(v:TransferRecord){try{const next=await accountingApi.reverseTransfer(v.id);transfers.value=transfers.value.map(x=>x.id===next.id?next:x);emit('notify','Transfer reversed.')}catch(e){error.value=String(e)}}
</script>
<template><div class="accounting-extra"><div v-if="error" class="form-error">{{error}}</div><template v-if="props.tab==='Expenses'"><SectionPanel title="Expenses" subtitle="Each expense posts a balanced debit to its category and a credit to Cash/Bank."><form class="finance-form" @submit.prevent="createExpense"><select v-model="expense.categoryAccountId"><option v-for="a in props.accounts.filter(x=>x.type==='expense'&&x.code!=='5000')" :key="a.id" :value="a.id">{{a.code}} · {{a.name}}</option></select><select v-model="expense.financialAccountId"><option v-for="a in props.financial" :key="a.id" :value="a.id">{{a.name}}</option></select><input v-model="expense.description" required placeholder="Description"/><input v-model="expense.payee" placeholder="Payee"/><select v-model="expense.supplierId"><option value="">No supplier</option><option v-for="s in props.suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select><input v-model="expense.amount" required inputmode="numeric" :placeholder="`Amount (${props.currencyUnit})`"/><button class="button button-primary" type="submit"><Plus :size="15"/> Post expense</button></form></SectionPanel><SectionPanel title="Expense history" subtitle="Posted expenses are reversed, never deleted."><div v-for="v in expenses" :key="v.id" class="accounting-row"><span><strong>{{v.expenseNumber}} · {{v.description}}</strong><small>{{formatDateTime(v.expenseDate)}} · {{formatMoney(v.amountRial,props.currencyUnit)}}</small></span><span class="payment-actions"><StatusBadge :label="v.status" :tone="v.status==='Posted'?'green':'slate'"/><button v-if="v.status==='Posted'" class="text-button" @click="reverseExpense(v)"><RotateCcw :size="14"/> Reverse</button></span></div></SectionPanel></template><template v-else><SectionPanel title="Transfers / treasury" subtitle="Move value between Cash and Bank without income or expense effect."><form class="finance-form" @submit.prevent="createTransfer"><select v-model="transfer.sourceFinancialAccountId"><option v-for="a in props.financial" :key="a.id" :value="a.id">From {{a.name}}</option></select><select v-model="transfer.destinationFinancialAccountId"><option v-for="a in props.financial" :key="a.id" :value="a.id">To {{a.name}}</option></select><input v-model="transfer.amount" required inputmode="numeric" :placeholder="`Amount (${props.currencyUnit})`"/><input v-model="transfer.reference" placeholder="Reference"/><button class="button button-primary" type="submit"><ArrowRightLeft :size="15"/> Post transfer</button></form></SectionPanel><SectionPanel title="Transfer history" subtitle="Source is credited and destination is debited."><div v-for="v in transfers" :key="v.id" class="accounting-row"><span><strong>{{v.transferNumber}} · {{v.reference||'Transfer'}}</strong><small>{{formatDateTime(v.transferDate)}} · {{formatMoney(v.amountRial,props.currencyUnit)}}</small></span><span class="payment-actions"><StatusBadge :label="v.status" :tone="v.status==='Posted'?'green':'slate'"/><button v-if="v.status==='Posted'" class="text-button" @click="reverseTransfer(v)"><RotateCcw :size="14"/> Reverse</button></span></div></SectionPanel></template></div></template>
<style scoped>.accounting-extra{display:grid;gap:16px}.finance-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.finance-form input,.finance-form select{min-width:0;width:100%;box-sizing:border-box}.finance-form button{justify-self:start}@media(max-width:800px){.finance-form{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.finance-form{grid-template-columns:1fr}}</style>
